CREATE POLICY "Panel uploads website images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='site-images' AND (storage.foldername(name))[1] IN ('courses','categories','classes','webinars','seminars','ebooks','notifications','settings','banners') AND (public.has_panel_permission((storage.foldername(name))[1],'create') OR public.has_panel_permission((storage.foldername(name))[1],'edit')));
CREATE POLICY "Panel reads website images" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='site-images' AND (public.has_panel_permission((storage.foldername(name))[1],'view') OR public.has_panel_permission((storage.foldername(name))[1],'create') OR public.has_panel_permission((storage.foldername(name))[1],'edit')));
CREATE POLICY "Public reads published website images" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id='site-images' AND (EXISTS(SELECT 1 FROM public.courses WHERE status='published' AND thumbnail_url LIKE '%/api/public/site-file/'||storage.objects.name) OR EXISTS(SELECT 1 FROM public.ebooks WHERE status='published' AND cover_url LIKE '%/api/public/site-file/'||storage.objects.name) OR EXISTS(SELECT 1 FROM public.class_sessions WHERE status='scheduled' AND thumbnail_url LIKE '%/api/public/site-file/'||storage.objects.name) OR EXISTS(SELECT 1 FROM public.course_categories WHERE is_visible AND icon_url LIKE '%/api/public/site-file/'||storage.objects.name) OR EXISTS(SELECT 1 FROM public.banners WHERE active AND image_url LIKE '%/api/public/site-file/'||storage.objects.name) OR public.app_branding() LIKE '%/api/public/site-file/'||storage.objects.name));